import { getSurveilansById } from "@/services/surveilans";
import { redirect } from "next/navigation";
import { ArrowLeft, Save } from "lucide-react";
import Link from "next/link";

export default async function EditRiwayatPage({ params }: { params: { id: string } }) {
  const { id } = await params;
  const data = await getSurveilansById(id);

  if (!data) redirect("/dashboard/perawat/riwayat");

  return (
    <div className="space-y-6 text-slate-600">
      <div className="flex items-center gap-4">
        <Link 
          href="/dashboard/perawat/riwayat"
          className="p-2 bg-white border border-slate-100 rounded-xl text-slate-400 hover:text-blue-600 transition-all"
        >
          <ArrowLeft size={20} />
        </Link>
        <div>
          <h1 className="text-xl font-semibold text-slate-800">Edit Laporan</h1>
          <p className="text-sm font-medium text-slate-500 uppercase">Pasien: {data.nama_pasien} (RM: {data.no_rm})</p>
        </div>
      </div>

      <div className="bg-white p-8 rounded-3xl border border-slate-100 shadow-sm">
        {/* Ayah bisa memasukkan kembali Form Input di sini */}
        {/* Pastikan value input diisi dengan data.{nama_kolom} */}
        <p className="text-sm text-slate-400 italic">
          Gunakan Server Action untuk melakukan update ke tabel surveilans_harian.
        </p>
        
        <div className="mt-8 flex justify-end">
          <button className="flex items-center gap-2 bg-blue-600 text-white px-6 py-3 rounded-xl font-medium hover:bg-blue-700 transition-all shadow-lg shadow-blue-100">
            <Save size={18} />
            Simpan Perubahan
          </button>
        </div>
      </div>
    </div>
  );
}